-- Fases 3, 4 e 5: produção, pessoas, dívidas e histórico oficial de relatórios.
CREATE TABLE IF NOT EXISTS public.relatorios_gerados (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id uuid NOT NULL REFERENCES public.empresas(id),usuario_id uuid REFERENCES public.usuarios(id),tipo text NOT NULL,inicio date,fim date,formato text NOT NULL DEFAULT 'gerencial',created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.relatorios_gerados ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.relatorios_gerados FROM PUBLIC,anon,authenticated;
CREATE INDEX IF NOT EXISTS idx_relatorios_gerados_empresa_created ON public.relatorios_gerados(empresa_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.app_admin_relatorio_operacional(p_token text,p_tipo text,p_inicio date DEFAULT NULL,p_fim date DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','extensions' AS $function$
DECLARE v record; v_inicio date:=COALESCE(p_inicio,date_trunc('month',current_date)::date); v_fim date:=COALESCE(p_fim,current_date); v_tipo text:=lower(trim(coalesce(p_tipo,'')));
BEGIN
SELECT * INTO v FROM public.app_tenant_usuario(p_token) LIMIT 1;
IF v.usuario_id IS NULL OR v.perfil NOT IN ('admin','administrador','gestor') THEN RETURN jsonb_build_object('sucesso',false,'erro','Acesso negado'); END IF;
IF v_tipo='producao_status' THEN RETURN jsonb_build_object('sucesso',true,'tipo',v_tipo,'inicio',v_inicio,'fim',v_fim,'linhas',(SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.quantidade DESC),'[]'::jsonb) FROM (SELECT status,count(*)::integer quantidade,COALESCE(sum(valor_total),0) valor_total FROM public.ordens_servico WHERE empresa_id=v.empresa_id AND data_entrada BETWEEN v_inicio AND v_fim GROUP BY status ORDER BY 2 DESC LIMIT 20)x)); END IF;
IF v_tipo='producao_clientes' THEN RETURN jsonb_build_object('sucesso',true,'tipo',v_tipo,'inicio',v_inicio,'fim',v_fim,'linhas',(SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.valor_total DESC),'[]'::jsonb) FROM (SELECT COALESCE(c.nome,'Cliente não informado') cliente,count(o.id)::integer ordens,COALESCE(sum(o.quantidade),0)::integer quantidade,COALESCE(sum(o.valor_total),0) valor_total FROM public.ordens_servico o LEFT JOIN public.clientes c ON c.id=o.cliente_id WHERE o.empresa_id=v.empresa_id AND o.data_entrada BETWEEN v_inicio AND v_fim GROUP BY 1 ORDER BY 4 DESC LIMIT 100)x)); END IF;
IF v_tipo='produtividade' THEN RETURN jsonb_build_object('sucesso',true,'tipo',v_tipo,'inicio',v_inicio,'fim',v_fim,'linhas',(SELECT jsonb_build_array(jsonb_build_object('indicador','Ordens recebidas','valor',count(*)),jsonb_build_object('indicador','Peças recebidas','valor',COALESCE(sum(quantidade),0)),jsonb_build_object('indicador','Valor produzido','valor',COALESCE(sum(valor_total),0)),jsonb_build_object('indicador','Ordens entregues','valor',count(*) FILTER(WHERE status='entregue'))) FROM public.ordens_servico WHERE empresa_id=v.empresa_id AND data_entrada BETWEEN v_inicio AND v_fim)); END IF;
IF v_tipo='quadro_funcionarios' THEN RETURN jsonb_build_object('sucesso',true,'tipo',v_tipo,'inicio',v_inicio,'fim',v_fim,'linhas',(SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.quantidade DESC),'[]'::jsonb) FROM (SELECT 'Vínculo · '||COALESCE(tipo_vinculo,'não informado') grupo,count(*)::integer quantidade FROM public.funcionarios WHERE empresa_id=v.empresa_id AND ativo GROUP BY tipo_vinculo UNION ALL SELECT 'Cargo · '||COALESCE(cargo,'não informado'),count(*)::integer FROM public.funcionarios WHERE empresa_id=v.empresa_id AND ativo GROUP BY cargo LIMIT 100)x)); END IF;
IF v_tipo='ponto_jornada' THEN RETURN jsonb_build_object('sucesso',true,'tipo',v_tipo,'inicio',v_inicio,'fim',v_fim,'linhas',(SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.quantidade DESC),'[]'::jsonb) FROM (SELECT COALESCE(r.status,'sem status') status,count(*)::integer quantidade FROM public.registros_ponto r JOIN public.funcionarios f ON f.id=r.funcionario_id WHERE f.empresa_id=v.empresa_id AND r.data BETWEEN v_inicio AND v_fim GROUP BY r.status LIMIT 20)x)); END IF;
IF v_tipo='absenteismo' THEN RETURN jsonb_build_object('sucesso',true,'tipo',v_tipo,'inicio',v_inicio,'fim',v_fim,'linhas',(SELECT jsonb_build_array(jsonb_build_object('tipo','Faltas registradas','quantidade',count(*) FILTER(WHERE r.status='falta'),'dias',count(*) FILTER(WHERE r.status='falta')),jsonb_build_object('tipo','Registros totais','quantidade',count(*),'dias',count(*))) FROM public.registros_ponto r JOIN public.funcionarios f ON f.id=r.funcionario_id WHERE f.empresa_id=v.empresa_id AND r.data BETWEEN v_inicio AND v_fim)); END IF;
IF v_tipo='ferias_afastamentos' THEN RETURN jsonb_build_object('sucesso',true,'tipo',v_tipo,'inicio',v_inicio,'fim',v_fim,'linhas',(SELECT COALESCE(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT 'Férias' tipo,count(*)::integer quantidade,count(*) FILTER(WHERE inicio BETWEEN current_date AND current_date+30)::integer proximos FROM public.rh_ferias f JOIN public.funcionarios u ON u.id=f.funcionario_id WHERE u.empresa_id=v.empresa_id AND COALESCE(f.fim,f.inicio)>=v_inicio AND f.inicio<=v_fim UNION ALL SELECT 'Afastamentos',count(*)::integer,count(*) FILTER(WHERE inicio BETWEEN current_date AND current_date+30)::integer FROM public.rh_afastamentos a JOIN public.funcionarios u ON u.id=a.funcionario_id WHERE u.empresa_id=v.empresa_id AND COALESCE(a.fim,current_date+3650)>=v_inicio AND a.inicio<=v_fim LIMIT 10)x)); END IF;
IF v_tipo='dividas_posicao' THEN RETURN jsonb_build_object('sucesso',true,'tipo',v_tipo,'inicio',v_inicio,'fim',v_fim,'linhas',(SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.valor DESC),'[]'::jsonb) FROM (SELECT status,count(*)::integer quantidade,COALESCE(sum(saldo_devedor),0) valor FROM public.dividas_gestao WHERE empresa_id=v.empresa_id AND status<>'inativa' GROUP BY status LIMIT 20)x)); END IF;
IF v_tipo='dividas_credores' THEN RETURN jsonb_build_object('sucesso',true,'tipo',v_tipo,'inicio',v_inicio,'fim',v_fim,'linhas',(SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.saldo DESC),'[]'::jsonb) FROM (SELECT credor,count(*)::integer contratos,COALESCE(sum(saldo_devedor),0) saldo FROM public.dividas_gestao WHERE empresa_id=v.empresa_id AND status='ativa' GROUP BY credor ORDER BY 3 DESC LIMIT 100)x)); END IF;
RETURN jsonb_build_object('sucesso',false,'erro','Tipo de relatório operacional inválido');
END;$function$;
CREATE OR REPLACE FUNCTION public.app_admin_relatorio_registrar(p_token text,p_tipo text,p_inicio date,p_fim date,p_formato text DEFAULT 'gerencial') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','extensions' AS $function$ DECLARE v record; v_id uuid; BEGIN SELECT * INTO v FROM public.app_tenant_usuario(p_token) LIMIT 1; IF v.usuario_id IS NULL OR v.perfil NOT IN ('admin','administrador','gestor') THEN RETURN jsonb_build_object('sucesso',false,'erro','Acesso negado'); END IF; INSERT INTO public.relatorios_gerados(empresa_id,usuario_id,tipo,inicio,fim,formato) VALUES(v.empresa_id,v.usuario_id,p_tipo,p_inicio,p_fim,COALESCE(p_formato,'gerencial')) RETURNING id INTO v_id; RETURN jsonb_build_object('sucesso',true,'id',v_id); END;$function$;
CREATE OR REPLACE FUNCTION public.app_admin_relatorio_historico(p_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','extensions' AS $function$ DECLARE v record; BEGIN SELECT * INTO v FROM public.app_tenant_usuario(p_token) LIMIT 1; IF v.usuario_id IS NULL OR v.perfil NOT IN ('admin','administrador','gestor') THEN RETURN jsonb_build_object('sucesso',false,'erro','Acesso negado'); END IF; RETURN jsonb_build_object('sucesso',true,'linhas',(SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC),'[]'::jsonb) FROM (SELECT r.id,r.tipo,r.inicio,r.fim,r.formato,r.created_at,COALESCE(u.nome_exibicao,'Administrador') usuario FROM public.relatorios_gerados r LEFT JOIN public.usuarios u ON u.id=r.usuario_id WHERE r.empresa_id=v.empresa_id ORDER BY r.created_at DESC LIMIT 100)x)); END;$function$;
GRANT EXECUTE ON FUNCTION public.app_admin_relatorio_operacional(text,text,date,date) TO anon,authenticated;
GRANT EXECUTE ON FUNCTION public.app_admin_relatorio_registrar(text,text,date,date,text) TO anon,authenticated;
GRANT EXECUTE ON FUNCTION public.app_admin_relatorio_historico(text) TO anon,authenticated;
